<p><a class="button" href="/admin/content/<?=h($key)?>/create"><?=t('Добавить запись','Add record')?> +</a></p><div class="table-scroll"><table><thead><tr><th>ID</th><th><?=t('Название RU / EN','Title RU / EN')?></th><?php if($key==='products'):?><th><?=t('Цена','Price')?></th><?php endif;?><th><?=t('Опубликовано','Published')?></th><th><?=t('Действия','Actions')?></th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=(int)$row['id']?></td><td><?=h($row['title_ru'])?><br><span class="small"><?=h($row['title_en'])?></span></td><?php if($key==='products'):?><td><?=h(money((int)$row['price_minor']))?></td><?php endif;?><td><?=!empty($row['published'])?t('Да','Yes'):t('Нет','No')?></td><td class="actions"><a href="/admin/content/<?=h($key)?>/edit/<?=(int)$row['id']?>"><?=t('Изменить','Edit')?></a><form method="post" action="/admin/content/<?=h($key)?>/delete/<?=(int)$row['id']?>" data-confirm><?=csrfField()?><button class="link-button"><?=t('Удалить','Delete')?></button></form></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p><?=t('Записей пока нет.','No records yet.')?></p><?php endif;?>
